1	import type {
2	  WorkspaceBusy,
3	  WorkspaceStamp,
4	  WorkspaceSwitchResult,
5	} from "@shared/types/workspaces";
6	import type { WorkspaceGate } from "./gate";
7	import type { Availability, RelocateOutcome } from "./registry";
8	
9	export interface SwitchDeps {
10	  gate: WorkspaceGate;
11	  activeId(): string;
12	  isKnown(id: string): boolean;
13	  readOnly(): boolean;
14	  /** Probes the target folder; resolves its id afterwards (a pending entry may adopt one). */
15	  availability(id: string): Promise<{ availability: Availability; id: string }>;
16	  /** What is writing into the active workspace right now, if anything (the LOCKED state). */
17	  busy(): WorkspaceBusy | null;
18	  /**
19	   * Ask every window to flush pending saves, resolve unsaved editors (Save, Discard or
20	   * Cancel) and close what belongs to the old workspace. False when one cancelled or timed out.
21	   */
22	  prepareWindows(): Promise<boolean>;
23	  /** The switch is off after `prepareWindows`: windows go back to normal. */
24	  abortWindows(): void;
25	  /** Dismiss pending quiet-capture toasts and drop their retained bytes (after `persistActive`). */
26	  dropPendingCaptures(): void;
27	  /** Store `activeId` and the mirrored `vaultDirectory`. */
28	  persistActive(id: string): Promise<void>;
29	  /** Window title, tray, `workspaces:changed` and `library:changed`. */
30	  afterCommit(stamp: WorkspaceStamp): void;
31	}
32	
33	let inFlight = false;
34	
35	/**
36	 * The switch transaction (ADR 0032, decision 7). Every switch entry point goes through it.
37	 * Anything that fails before the commit leaves the old workspace active and unchanged.
38	 *
39	 * The windows are asked to prepare BEFORE the gate closes: preparing means flushing an
40	 * editor's pending save, which is an item-scoped call that must still reach the old
41	 * workspace. Only then does the gate refuse new calls and wait for the running ones.
42	 */
43	export async function switchWorkspace(
44	  deps: SwitchDeps,
45	  id: string,
46	): Promise<WorkspaceSwitchResult> {
47	  if (deps.readOnly()) return { ok: false, reason: "read-only" };
48	  if (!deps.isKnown(id)) return { ok: false, reason: "unknown" };
49	  if (id === deps.activeId()) return { ok: true };
50	  const busy = deps.busy();
51	  if (busy) return { ok: false, reason: busy };
52	  if (inFlight) return { ok: false, reason: "cancelled" };
53	  inFlight = true;
54	  try {
55	    const probed = await deps.availability(id);
56	    if (probed.availability.state !== "available") return { ok: false, reason: "unavailable" };
57	    const target = probed.id;
58	
59	    if (!(await deps.prepareWindows())) {
60	      deps.abortWindows();
61	      return { ok: false, reason: "cancelled" };
62	    }
63	    // A take may have started while a window was asking about unsaved work.
64	    const late = deps.busy();
65	    if (late) {
66	      deps.abortWindows();
67	      return { ok: false, reason: late };
68	    }
69	
70	    await deps.gate.close();
71	    try {
72	      await deps.persistActive(target);
73	    } catch (error) {
74	      deps.gate.reopen();
75	      deps.abortWindows();
76	      throw error;
77	    }
78	    // Only now is the switch certain: a failed persist keeps the old workspace's captures.
79	    deps.dropPendingCaptures();
80	    deps.afterCommit(deps.gate.commit(target));
81	    return { ok: true };
82	  } finally {
83	    inFlight = false;
84	  }
85	}
86	
87	/** What a transaction on the active workspace needs from the host (a subset of `SwitchDeps`). */
88	export type ActiveTransactionDeps = Pick<
89	  SwitchDeps,
90	  "gate" | "busy" | "prepareWindows" | "abortWindows" | "dropPendingCaptures" | "afterCommit"
91	>;
92	
93	/**
94	 * The same transaction for a change to the ACTIVE workspace that is not a switch: its folder
95	 * moved ("Change folder…"). Windows prepare first (a pending save must still reach the old
96	 * folder), the gate drains, `apply` stores the change, and the generation bumps, so every
97	 * window re-lists the library from the new folder. A refused or failed `apply` leaves the
98	 * workspace as it was. Shares the in-flight guard with `switchWorkspace`: they never overlap.
99	 */
100	export async function relocateActive(
101	  deps: ActiveTransactionDeps,
102	  id: string,
103	  apply: () => Promise<RelocateOutcome>,
104	): Promise<RelocateOutcome> {
105	  const busy = deps.busy();
